mapper.sql:
where 1=1
and ccue_llave = #{key}
and ccue_estado = #{state}
and ccue_catalogo = #{catalog}
and ccue_wbs = #{wbs}
and ccue_nombre = #{name}
and ccue_codigo = #{code}
and ccue_padre = #{parent}
and ncue_nivel = #{level}
and ccue_tipo = #{type}
and ccue_naturaleza = #{operation}
and ccue_documento = #{document}
and (upper(ccue_nombre) like upper('%' || #{filter} || '%') or upper(ccue_codigo) like upper('%' || #{filter} || '%'))
